import{_ as a,o,c as t,a5 as r}from"./chunks/framework.DJo0M80U.js";const u=JSON.parse('{"title":"HJ32 密码截取","description":"中等 通过率：28.15% 时间限制：1秒 空间限制：32M 知识点 字符串 动态规划 描述 Catcher是MCA国的情报员，他工作时发现敌国会用一些对称的密码进行通信，比如像这些ABBA，ABA，A，123321，但是他们有时会在开始或结束时加入一些无关的字符以防止别国破解。","frontmatter":{"title":"HJ32 密码截取","date":"2026-08-11T00:00:00.000Z","categories":["前端面试与实战"],"tags":["前端面试","算法","求职","教程","OneNote","算法训练"],"description":"中等 通过率：28.15% 时间限制：1秒 空间限制：32M 知识点 字符串 动态规划 描述 Catcher是MCA国的情报员，他工作时发现敌国会用一些对称的密码进行通信，比如像这些ABBA，ABA，A，123321，但是他们有时会在开始或结束时加入一些无关的字符以防止别国破解。","sidebarWeight":17,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/a-吊打面试官/算法题/动态规划【中等】/HJ32 密码截取.md"},"headers":[],"relativePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ32 密码截取.md","filePath":"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ32 密码截取.md"}'),n={name:"posts/前端面试与实战/03-算法训练/动态规划【中等】/HJ32 密码截取.md"};function i(d,e,l,s,c,p){return o(),t("div",null,[...e[0]||(e[0]=[r('<div><h1 id="hj32-密码截取" tabindex="-1">HJ32 密码截取 <a class="header-anchor" href="#hj32-密码截取" aria-label="Permalink to &quot;HJ32 密码截取&quot;">​</a></h1><blockquote><p>本节目标：理解“HJ32 密码截取”的核心思路，并能把它用于实际开发或面试表达。 中等 通过率：28.15% 时间限制：1秒 空间限制：32M 知识点 ==字符串====动态规划== <strong>描述</strong> Catcher是MCA国的情报员，他工作时发现敌国会用一些对称的密码进行通信，比如像这些ABBA，ABA，A，123321，但是他们有时会在开始或结束时加入一些无关的字符以防止别国破解。比如进行下列变化 ABBA-&gt;12ABBA,ABA-&gt;ABAKK,123321-&gt;51233214　。因为截获的串太长了，而且存在多种可能的情况（abaaab可看作是aba,或baaab的加密形式），Cathcer的工作量实在是太大了，他只能向电脑高手求助，你能帮Catcher找出最长的有效密码串吗？ 数据范围：字符串长度满足 1≤<em>n</em>≤2500 <strong>输入描述：</strong> 输入一个字符串（字符串的长度不超过2500） <strong>输出描述：</strong> 返回有效密码串的最大长度 <strong>示例1</strong> 输入： ABBA 输出： 4 <strong>示例2</strong> 输入： ABBBA 输出： 5 <strong>示例3</strong> 输入： 12HHHHA 输出： 4</p></blockquote><p>解决这类问题的一种有效方法是使用动态规划来找到最长的回文子串。动态规划的基本思想是将问题分解成相关的子问题，然后结合子问题的解来生成原问题的解。</p><h3 id="思路" tabindex="-1">思路 <a class="header-anchor" href="#思路" aria-label="Permalink to &quot;思路&quot;">​</a></h3><p>定义一个二维数组 <code>dp</code>，其中 <code>dp[i][j]</code> 表示字符串从索引 <code>i</code> 到索引 <code>j</code> 的子串是否是回文串。如果是回文串，<code>dp[i][j] = True</code>，否则 <code>dp[i][j] = False</code>。</p><ol><li><p><strong>初始化</strong>：对于任意字符串 <code>s</code>，长度为 1 的子串总是回文串，所以 <code>dp[i][i] = True</code>。长度为 2 的子串如果两个字符相同，则是回文串，所以如果 <code>s[i] == s[i+1]</code>，则 <code>dp[i][i+1] = True</code>。</p></li><li><p><strong>状态转移</strong>：对于长度大于 2 的子串，如果 <code>s[i] == s[j]</code> 且 <code>dp[i+1][j-1]</code> 是回文串，则 <code>dp[i][j]</code> 也是回文串。</p></li><li><p><strong>寻找最长回文子串</strong>：在填充 <code>dp</code> 数组的过程中记录最长回文子串的长度。</p></li></ol><h3 id="实现" tabindex="-1">实现 <a class="header-anchor" href="#实现" aria-label="Permalink to &quot;实现&quot;">​</a></h3><p>def longest_palindrome(s): n = len(s) dp = [[False] * n for _ in range(n)] max_len = 0</p><h1 id="从字符串的末尾开始向前遍历" tabindex="-1">从字符串的末尾开始向前遍历 <a class="header-anchor" href="#从字符串的末尾开始向前遍历" aria-label="Permalink to &quot;从字符串的末尾开始向前遍历&quot;">​</a></h1><p>for i in range(n-1, -1, -1): for j in range(i, n):</p><h1 id="字符串从i到j的子串如果是回文" tabindex="-1">字符串从i到j的子串如果是回文 <a class="header-anchor" href="#字符串从i到j的子串如果是回文" aria-label="Permalink to &quot;字符串从i到j的子串如果是回文&quot;">​</a></h1><p>if s[i] == s[j] and (j - i &lt; 3 or dp[i+1][j-1]): dp[i][j] = True max_len = max(max_len, j - i + 1) return max_len</p><h1 id="输入字符串" tabindex="-1">输入字符串 <a class="header-anchor" href="#输入字符串" aria-label="Permalink to &quot;输入字符串&quot;">​</a></h1><p>s = input()</p><h1 id="输出最长有效密码串的长度" tabindex="-1">输出最长有效密码串的长度 <a class="header-anchor" href="#输出最长有效密码串的长度" aria-label="Permalink to &quot;输出最长有效密码串的长度&quot;">​</a></h1><p>print(longest_palindrome(s))</p><p>这段代码首先初始化了一个二维的布尔数组 <code>dp</code> 来记录子串是否是回文串。然后，通过双重循环遍历字符串的所有可能的子串，利用动态规划的方法更新 <code>dp</code> 数组的值。最后，返回找到的最长回文子串的长度。</p><p>要优化找到最长回文子串的算法，我们可以考虑使用 <strong>中心扩展法</strong>。这个方法的核心思想是：对于字符串中的每个字符（或字符对），尝试将其作为回文子串的中心，然后向两边扩展，直到不能形成更长的回文子串为止。</p><p>中心扩展法的优点是它不需要使用额外的空间来存储子问题的解，因此空间复杂度降低到 O(1)，而时间复杂度仍然是 O(n^2)，但在实践中通常比动态规划方法更快，因为它避免了不必要的计算。</p><h3 id="实现步骤" tabindex="-1">实现步骤 <a class="header-anchor" href="#实现步骤" aria-label="Permalink to &quot;实现步骤&quot;">​</a></h3><ol><li>遍历字符串的每个字符，将每个字符或字符对作为回文中心。</li><li>从中心向两边扩展，检查并更新最长回文子串的长度。</li><li>注意处理两种情况：奇数长度的回文和偶数长度的回文。</li></ol><h3 id="代码示例" tabindex="-1">代码示例 <a class="header-anchor" href="#代码示例" aria-label="Permalink to &quot;代码示例&quot;">​</a></h3><p>def longest_palindrome(s): def expand_around_center(left, right):</p><h1 id="从中心向两边扩展" tabindex="-1">从中心向两边扩展 <a class="header-anchor" href="#从中心向两边扩展" aria-label="Permalink to &quot;从中心向两边扩展&quot;">​</a></h1><p>while left &gt;= 0 and right &lt; len(s) and s[left] == s[right]: left -= 1 right += 1</p><h1 id="返回扩展后的回文子串的长度" tabindex="-1">返回扩展后的回文子串的长度 <a class="header-anchor" href="#返回扩展后的回文子串的长度" aria-label="Permalink to &quot;返回扩展后的回文子串的长度&quot;">​</a></h1><p>return right - left - 1 start, end = 0, 0 for i in range(len(s)):</p><h1 id="以-s-i-为中心的最长回文子串" tabindex="-1">以 s[i] 为中心的最长回文子串 <a class="header-anchor" href="#以-s-i-为中心的最长回文子串" aria-label="Permalink to &quot;以 s[i] 为中心的最长回文子串&quot;">​</a></h1><p>len1 = expand_around_center(i, i)</p><h1 id="以-s-i-和-s-i-1-为中心的最长回文子串" tabindex="-1">以 s[i] 和 s[i+1] 为中心的最长回文子串 <a class="header-anchor" href="#以-s-i-和-s-i-1-为中心的最长回文子串" aria-label="Permalink to &quot;以 s[i] 和 s[i+1] 为中心的最长回文子串&quot;">​</a></h1><p>len2 = expand_around_center(i, i + 1)</p><h1 id="取两者之间的最大值" tabindex="-1">取两者之间的最大值 <a class="header-anchor" href="#取两者之间的最大值" aria-label="Permalink to &quot;取两者之间的最大值&quot;">​</a></h1><p>max_len = max(len1, len2) if max_len &gt; end - start: start = i - (max_len - 1) // 2 end = i + max_len // 2 # 最长回文子串的长度 return end - start + 1</p><h1 id="输入字符串-1" tabindex="-1">输入字符串 <a class="header-anchor" href="#输入字符串-1" aria-label="Permalink to &quot;输入字符串&quot;">​</a></h1><p>s = input()</p><h1 id="输出最长有效密码串的长度-1" tabindex="-1">输出最长有效密码串的长度 <a class="header-anchor" href="#输出最长有效密码串的长度-1" aria-label="Permalink to &quot;输出最长有效密码串的长度&quot;">​</a></h1><p>print(longest_palindrome(s)) 这段代码通过中心扩展法计算了给定字符串中最长回文子串的长度。<code>expand_around_center</code> 函数负责从给定的中心位置向两边扩展，寻找最长的回文子串，并返回其长度。然后，主函数遍历字符串的每个位置，分别考虑奇数长度和偶数长度的回文子串，最后返回找到的最长回文子串的长度。这种方法相比动态规划，虽然时间复杂度相同，但由于减少了冗余计算，通常执行速度更快，且空间复杂度更低。</p><p>奇数长度的回文和偶数长度的回文 在寻找最长回文子串的问题中，考虑两种长度的回文子串是必要的，因为回文子串可以是奇数长度也可以是偶数长度。这两种情况需要分别处理：</p><ol><li><p><strong>奇数长度的回文子串</strong>：这种类型的回文以某个字符为中心，然后向两边扩展。例如，在字符串 &quot;racecar&quot; 中，以字符 &#39;e&#39; 为中心的最长回文子串是 &quot;racecar&quot; 本身。</p></li><li><p><strong>偶数长度的回文子串</strong>：这种类型的回文以某两个相邻字符之间的位置为中心，然后向两边扩展。例如，在字符串 &quot;aabbaa&quot; 中，以字符 &#39;b&#39; 和 &#39;b&#39; 之间为中心的最长回文子串是 &quot;aabbaa&quot; 本身。</p></li></ol><p>为了涵盖这两种情况，我们需要分别检查以 <code>s[i]</code> 为中心的奇数长度回文子串（<code>len1</code>），和以 <code>s[i]</code> 与 <code>s[i+1]</code> 为中心的偶数长度回文子串（<code>len2</code>）。这样可以确保不遗漏任何可能的回文子串，无论其长度是奇数还是偶数。</p><p><code>expand_around_center</code> 函数的作用是从中心向两边扩展，尝试找到最长的回文子串，并返回该回文子串的长度。对于奇数长度的回文，中心是一个字符；对于偶数长度的回文，中心是两个字符之间的空隙。这就是为什么要计算两个 <code>len</code> 的原因，以确保能够找到所有可能的回文子串，并从中选出最长的那一个。</p><p>这种方法相比动态规划有更好的时间复杂度，因为它避免了不必要的计算，直接从每个可能的中心点向外扩展寻找回文子串，时间复杂度为 O(n^2)，其中 n 是字符串的长度。尽管最坏情况下时间复杂度仍然是 O(n^2)，但在实际应用中，由于很多扩展很快就会停止，所以这种方法在实践中通常比动态规划要快。</p></div>',1)])])}const _=a(n,[["render",i]]);export{u as __pageData,_ as default};
